#!/usr/bin/env python3
"""Movement parts and bilingual book; run after generate_golem_tasks.py."""
import json
from pathlib import Path
A=Path(__file__).resolve().parents[1]/'src/modern/resources/assets/thaumcraft'
labels={
 'part_5':('Legs','Patas'),'walker':('Walker','Caminantes'),'roller':('Wheels','Ruedas'),'climber':('Climber','Trepadoras'),'flyer':('Levitator','Levitadoras'),'wheeled':('Wheeled','Con ruedas')}
guides={
 'research.MINDCLOCKWORK.stage.3':('Build the compact press using the recipe. Choose material, head, arms, addon and legs. Hover Build for the complete cost and traits. All components are taken atomically; Machina from the sides/bottom completes the paid job across restarts. Walkers preserve the old costs. Wheels replace the walker base with two bowls and leather, retain a mechanism and move 25% faster with a lower automatic step. Hauler leather adds to wheel leather. Deploy the physical golem; bell cycles Work/Follow/Stay, sneak bell packs without healing and drops its real cargo. Design and legs persist in the item and entity. Mobility uses collisions and loaded chunks. Native shapes distinguish wheels and a levitator; original OBJ models/animations remain pending.',
 'Fabrica la prensa compacta. Elige material, cabeza, brazos, mejora y patas. Pasa el cursor sobre Construir para ver materiales y rasgos completos. El pago es atómico; Machina por los lados/debajo completa el trabajo pagado incluso tras reiniciar. Caminar mantiene el coste anterior. Ruedas sustituye el material de las patas por dos cuencos y cuero, conserva un mecanismo y aumenta la velocidad un 25%, con menor escalón automático. El cuero de Porteador se suma al de las ruedas. Coloca el gólem físico; la campana alterna Trabajar/Seguir/Esperar, agachado lo recoge sin curarlo y deja caer su carga real. Diseño y patas sobreviven en el objeto y la entidad. Usa colisiones y chunks cargados. Formas nativas distinguen ruedas y levitador; pendientes modelos OBJ y animaciones originales.'),
 'research.GOLEMCLIMBER.stage.1':('Unlock Climber legs, requiring this research in both press and placement. They keep the walker base and add four flint and one extra mechanism. Spider-style navigation can climb solid walls to higher tasks. A reachable wall and space at its top are required; no teleporting, wall clipping or ceiling adhesion. They remain subject to task radius, owner/channel, visibility, collision and redstone rules. They do not take fall damage.',
 'Desbloquea patas Trepadoras; la prensa y la colocación exigen esta investigación. Conservan el material caminante y añaden cuatro pedernales y un mecanismo extra. La navegación de araña permite trepar paredes sólidas hacia tareas elevadas. Necesitan una pared accesible y espacio arriba; no se teletransportan, atraviesan muros ni se adhieren a techos. Se mantienen radio, propietario/canal, visibilidad, colisiones y redstone. No sufren daño de caída.'),
 'research.GOLEMFLYER.stage.1':('Unlock Levitator legs, requiring this research in press and placement. They replace the walker base with a levitator, four brass plates and a slime ball, retaining a mechanism. They add Flyer and Fragile before addon traits cancel opposites. Flight is 33% slower than that material design on foot. Native flying navigation carries physical cargo across gaps and to higher inventories, routing around obstacles in loaded chunks. No gravity or fall damage; Stay and offline owners stop and hover rather than continuing the old route. It does not enable work through walls, distant seals or unloaded destinations.',
 'Desbloquea patas Levitadoras; la prensa y la colocación exigen esta investigación. Sustituyen el material caminante por un levitador, cuatro placas de latón y una bola de slime, conservando un mecanismo. Añaden Volador y Frágil antes de cancelar opuestos con las mejoras. Vuelan un 33% más despacio que ese diseño a pie. La navegación aérea transporta carga física sobre huecos y hasta inventarios elevados, rodeando obstáculos dentro de chunks cargados. Sin gravedad ni daño de caída; Esperar y el dueño desconectado detienen el recorrido y mantienen la altura. No permiten trabajar a través de paredes, con sellos lejanos ni en destinos descargados.')}
for i,loc in enumerate(['en_us','es_es']):
 p=A/f'lang/{loc}.json';v=json.loads(p.read_text());v.update({'golem.thaumcraft.'+k:pair[i] for k,pair in labels.items()});v.update({k:pair[i] for k,pair in guides.items()});p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
print('Walker/Wheels/Climber/Levitator labels and research guides generated.')

# Functional levitator dependency, including the original arcane crafting payment.
D=A.parents[1]/'data/thaumcraft'
def save(p,v):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
recipe={'type':'thaumcraft:arcane','research':'LEVITATOR','vis':35,'crystals':{'aer':1},'recipe':{'type':'minecraft:crafting_shaped','pattern':['WIW','BNB','WGW'],'key':{'W':'#minecraft:planks','I':'thaumcraft:plate_thaumium','B':'thaumcraft:plate_iron','N':'#thaumcraft:nitor','G':'thaumcraft:mechanism_simple'},'result':{'id':'thaumcraft:levitator'}}}
save(D/'recipe/arcane/levitator.json',recipe)
variants={}
for face,x,y in [('up',0,0),('down',180,0),('north',90,0),('south',90,180),('west',90,270),('east',90,90)]:
 for powered in [False,True]:variants[f'facing={face},powered={str(powered).lower()}']={'model':'thaumcraft:block/levitator_'+('off' if powered else 'on'),'x':x,'y':y}
save(A/'blockstates/levitator.json',{'variants':variants})
for state in ['on','off']:save(A/f'models/block/levitator_{state}.json',{'parent':'minecraft:block/cube_bottom_top','textures':{'top':f'thaumcraft:blocks/levitator_top_{state}','side':f'thaumcraft:blocks/levitator_side_{state}','bottom':'thaumcraft:blocks/levitator_bottom'}})
save(A/'items/levitator.json',{'model':{'type':'minecraft:model','model':'thaumcraft:block/levitator_off'}})
save(D/'loot_table/blocks/levitator.json',{'type':'minecraft:block','pools':[{'rolls':1,'entries':[{'type':'minecraft:item','name':'thaumcraft:levitator'}]}]})
save(D/'tags/item/nitor.json',{'replace':False,'values':['thaumcraft:nitor_'+k for k in ['white','orange','magenta','lightblue','yellow','lime','pink','gray','silver','cyan','purple','blue','brown','green','red','black']]})
p=A/'knowledge/recipes.json';v=json.loads(p.read_text());lines=['Research: LEVITATOR','Result: thaumcraft:levitator','Vis: 35; crystal: aer x1','WIW / BNB / WGW','W: planks x4; I: thaumium plate; B: iron plates x2; N: any nitor; G: simple mechanism'];v['thaumcraft:Levitator']=lines;v['thaumcraft:levitator']=lines;save(p,v)
for i,loc in enumerate(['en_us','es_es']):
 p=A/f'lang/{loc}.json';v=json.loads(p.read_text());v['block.thaumcraft.levitator']=['Arcane Levitator','Levitador arcano'][i];v['block.thaumcraft.levitator.range']=['Range: %s blocks. Cost: %s / 1200 vis per entity-tick.','Alcance: %s bloques. Coste: %s / 1200 vis por entidad y tick.'][i];v['research.LEVITATOR.stage.2']=['Craft with 35 vis and one air crystal, four planks, one thaumium plate, two iron plates, any nitor and a simple mechanism. Place facing the beam direction. Empty-hand use cycles 4/8/16/32 blocks; redstone disables. The beam stops at collision or unloaded chunks. It pushes creatures and items using ordinary motion; sneak in an upward beam to descend. One vis charges a saved 1200-unit reserve; each entity-tick consumes twice the configured range. No target means no vis consumption. Also a component of golem levitator legs.','Fabrica con 35 vis y un cristal de aire: cuatro tablones, una placa de taumio, dos de hierro, cualquier nitor y un mecanismo simple. La cara de colocación dirige el haz. Clic con mano vacía alterna 4/8/16/32 bloques; redstone desactiva. El haz se detiene ante colisiones o chunks descargados. Impulsa criaturas y objetos con movimiento normal; agáchate en un haz ascendente para descender. Un vis carga una reserva guardada de 1200 unidades; cada entidad y tick consume el doble del alcance configurado. Sin objetivos no consume vis. También sirve para las patas levitadoras.'][i];save(p,v)
